class PfairTask:
    def __init__(self, e, p):
        self.e = e
        self.p = p
        self.wt = e / p

def calculate_lag(pfair_task, current_time, schedule_history):
    ideal_allocation = pfair_task.wt * current_time
    actual_allocation = sum(schedule_history[pfair_task][u] for u in range(current_time))
    return ideal_allocation - actual_allocation

def is_pfair_schedule(pfair_tasks, schedule_history, max_time):
    for t in range(max_time):
        for task in pfair_tasks:
            lag = calculate_lag(task, t, schedule_history)
            if not (-1 < lag < 1):
                return False
    return True

def get_pseudo_release(pfair_task, subtask_index):
    return math.floor((subtask_index - 1) / pfair_task.wt)

def get_pseudo_deadline(pfair_task, subtask_index):
    return math.ceil(subtask_index / pfair_task.wt)

def are_complementary(task_T, task_U):
    return task_T.wt + task_U.wt == 1

def assign_tasks_and_check_P2(tasks, processors):
    # ... (ASSIGN-TASKS logic as in P1 sketch)

    # After assignment, verify P2
    for p_idx in range(len(processors)):
        migrating_count = 0
        for task_idx, task in enumerate(tasks):
            # Check if task is migrating and assigned to p_idx
            if len(task.assigned_processors) == 2 and processors[p_idx] in task.assigned_processors:
                migrating_count += 1
        assert migrating_count <= 2, f"Processor {p_idx} has too many migrating tasks: {migrating_count}"

def assign_tasks_and_check_P3(tasks, processors):
    # ... (ASSIGN-TASKS logic as in P1 sketch)

    # After assignment, verify P3
    for p_idx in range(len(processors)):
        total_share_on_processor = 0.0
        for task_idx, task in enumerate(tasks):
            total_share_on_processor += task.shares.get(processors[p_idx], 0.0)
        assert total_share_on_processor <= 1.0 + 1e-9, f"Processor {p_idx} over-utilized: {total_share_on_processor}"
